import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address nonOwner, uint256 balance) public {
        // 1. Admissible domain: nonOwner != owner. Owner is address(this) from setUp.
        vm.assume(nonOwner != address(this));
        // Give the contract some ETH so there is something to withdraw.
        vm.deal(address(c), balance);

        // 2. Drive withdrawAll as nonOwner and observe whether it reverts.
        bool succeeded;
        vm.prank(nonOwner);
        try c.withdrawAll(nonOwner) {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        // 3. Universal property: a call from a non-owner MUST revert.
        // Reference holds this for all non-owners. Buggy version allows withdrawal (true).
        assertTrue(!succeeded);
    }
}

