pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address owner, address recipient, uint256 amount) public {
        vm.assume(owner != address(0));
        vm.assume(recipient != address(0));
        vm.assume(owner != recipient);
        vm.assume(amount > 0 && amount <= type(uint96).max);

        // deploy new C with fuzzed owner
        c = new C(owner);
        vm.deal(address(c), amount);

        uint256 recipientBalBefore = address(recipient).balance;
        uint256 msgSenderBalBefore = address(this).balance;

        vm.prank(owner);
        try c.withdrawAll(recipient) {
            // success, check balances
        } catch {
            // if it reverts, rule is vacuously true for this input (no state change)
            assertTrue(true);
            return;
        }

        uint256 recipientBalAfter = address(recipient).balance;
        uint256 msgSenderBalAfter = address(this).balance;

        // General rule: The non-owner recipient's balance must increase by exactly the contract's prior balance,
        // and the caller's balance must NOT increase (since caller is owner, not recipient).
        // Bug: sends to msg.sender, so recipient balance does not increase, but caller balance does.
        assertTrue(recipientBalAfter == recipientBalBefore + amount && msgSenderBalAfter == msgSenderBalBefore);
    }
}

